// DEMO MODE: when Supabase is not configured (local dev / CI / agent previews),
// read catalog data from src/data/demo-catalog.json (generated by
// `node scripts/build-demo-data.mjs` from the real seed SQL).
// Production with real NEXT_PUBLIC_SUPABASE_URL never uses this.
import catalog from '@/data/demo-catalog.json'
import type { Product, ProductLine } from '@/types'
import type { PricingRule } from '@/lib/pricing'

export function isDemoMode(): boolean {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL ?? ''
  return process.env.DEMO_MODE === '1' || !url || url.includes('placeholder')
}

const lines = new Map<string, ProductLine>(
  (catalog.product_lines as unknown as ProductLine[]).map((l) => [l.id, l]),
)

export const demoProducts: Product[] = (catalog.products as unknown as Product[]).map((p) => ({
  ...p,
  image_urls: Array.isArray(p.image_urls) ? p.image_urls : [],
  product_line: p.product_line_id ? lines.get(p.product_line_id) : undefined,
}))

export const demoPricingRules: PricingRule[] = catalog.pricing_rules as unknown as PricingRule[]
